const $=s=>document.querySelector(s), svg=$('#map');
let level=0,route=[],zoom=1,pan=[0,0],english=false;
const mean=pts=>({x:pts.reduce((a,p)=>a+p[0],0)/pts.length,y:pts.reduce((a,p)=>a+p[1],0)/pts.length});
const shapes=Object.fromEntries(STATION.platforms.map(p=>[p.number,p]));
const positions=Object.fromEntries(STATION.platforms.map(p=>[p.number,mean(p.points)]));
const nodes={hall:{...mean(STATION.buildings.find(b=>b.kind==='hall').points),z:1},west:{x:473,y:183,z:-1},east:{x:432,y:371,z:-1}};
const landings={11:[462.39,214.69],10:[458.82,231.29],8:[455.54,246.53],5:[445.21,300.75],3:[439,317.5],2:[435,332.5],1:[432,353]};
const stairEnds={11:[[468.26,215.98],[456.12,213.33]],10:[[464.88,232.6],[452.86,229.98]],8:[[461.73,247.88],[449.24,245.15]],5:[[455.08,302.69],[435.66,298.68]],3:[[452.02,320.12],[426.56,315.1]],2:[[448.84,334.85],[423.48,329.82]],1:[[445.55,355.7],[419.15,350.41]]};
const edges=[];const link=(a,b)=>edges.push([a,b]);
Object.entries(positions).forEach(([n,p])=>nodes['p'+n]={...p,z:0});
const order=[11,10,8,5,3,2,1];
order.forEach((n,i)=>{const [x,y]=landings[n];nodes['t'+n]={x,y,z:-1};stairEnds[n].forEach(([sx,sy],j)=>{const id='s'+n+'_'+j;nodes[id]={x:sx,y:sy,z:0};link('t'+n,id);link(id,'p'+n)});if(i)link('t'+order[i-1],'t'+n)});
link('west','t11');link('t1','east');link('hall','p5');for(const [a,b]of [[7,8],[9,8],[6,5],[4,3]])link('p'+a,'p'+b);
function findRoute(start,end){const dist={[start]:0},prev={},pending=new Set(Object.keys(nodes));while(pending.size){const at=[...pending].sort((a,b)=>(dist[a]??Infinity)-(dist[b]??Infinity))[0];if(!Number.isFinite(dist[at]))return [];pending.delete(at);if(at===end){const out=[end];while(prev[out[0]])out.unshift(prev[out[0]]);return out}for(const [a,b]of edges){const next=a===at?b:b===at?a:null;if(!next||!pending.has(next))continue;const A=nodes[at],B=nodes[next],d=dist[at]+Math.hypot(A.x-B.x,A.y-B.y)+(A.z!==B.z?20:0);if(d<(dist[next]??Infinity)){dist[next]=d;prev[next]=at}}}return []}
const txt=(x,y,t,size=12,color='#a9bd9a',extra='')=>`<text x="${x}" y="${y}" fill="${color}" font-size="${size}" ${extra}>${t}</text>`;
const pts=p=>p.map(v=>v.join(',')).join(' ');
const line=(p,color,width,extra='')=>`<polyline points="${pts(p)}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round" stroke-linejoin="round" ${extra}/>`;
function stairs(st){let out='';for(let j=1;j<st.points.length;j++){const a=st.points[j-1],b=st.points[j],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy);if(!len)continue;out+=line([a,b],'#172a24',8);const count=Math.max(3,Math.round(len/2));for(let k=0;k<=count;k++){const f=k/count,x=a[0]+dx*f,y=a[1]+dy*f;out+=line([[x-dy/len*3,y+dx/len*3],[x+dy/len*3,y-dx/len*3]],'#d4d9a4',.9)}}return `<g class="stair" data-stair="${st.osmId}"><title>${english?'Stairs':'Schody'} ${st.levels.join(' ↔ ')}</title>${out}</g>`}
function render(){let s=`<defs><pattern id="grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#5e7757" stroke-opacity=".10"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="4" stdDeviation="3" flood-opacity=".18"/></filter></defs><rect width="1050" height="720" fill="url(#grid)"/><g transform="translate(${pan[0]} ${pan[1]}) translate(525 360) scale(${zoom}) translate(-525 -360)">`;
// All outlines share one metric projection. North points right, east down.
for(const tr of STATION.tracks)s+=line(tr.points,'#53634a',1,'opacity=".35"');
for(const b of STATION.buildings){const prominent=level===1?['hall','mall','parking'].includes(b.kind):!['hall','parking'].includes(b.kind);const fill=b.kind==='old'?'#354339':b.kind==='hall'?'#536344':b.kind==='mall'?'#334934':'#2b3d30';s+=`<polygon points="${pts(b.points)}" fill="${fill}" fill-opacity="${prominent?.9:.12}" stroke="#708462" stroke-width="1" stroke-opacity="${prominent?.7:.25}"/>`;}
if(level===0||level===-1){for(const p of STATION.platforms){const chosen=route.includes('p'+p.number);s+=`<g class="hit" data-platform="${p.number}" tabindex="0" role="button" aria-label="${english?'Platform':'Peron'} ${p.number}"><title>${english?'Platform':'Peron'} ${p.number}</title><polygon points="${pts(p.points)}" fill="${chosen?'#8b9f57':'#637953'}" fill-opacity="${level===-1?.18:.9}" stroke="${chosen?'#d7f77c':'#92a87c'}" stroke-width="${chosen?1.5:.8}"/></g>`;}}
for(const t of STATION.tunnels)s+=line(t.points,level===-1?'#101e19':'#8ca377',level===-1?11:2,level===-1?'':'opacity=".45" stroke-dasharray="3 4"');
if(level===-1)for(const t of STATION.tunnels)s+=line(t.points,'#88a572',7);
for(const b of STATION.bridge)s+=line(b.points,'#809078',9,'opacity=".38"');
if(level===1){const h=nodes.hall;s+=`<circle cx="${h.x}" cy="${h.y}" r="5" fill="#d7f77c"/>`;}
for(const st of STATION.stairs)if(st.levels.includes(level))s+=stairs(st);
// Demo graph uses geographic anchors; longitudinal platform walks remain unverified.
if(route.length){for(let i=1;i<route.length;i++){const a=nodes[route[i-1]],b=nodes[route[i]];if(a.z===level&&b.z===level){const segment=[[a.x,a.y],[b.x,b.y]];s+=line(segment,'#15261d',7)+line(segment,'#d7f77c',3.5,'stroke-dasharray="5 3"');}if(a.z!==b.z){const p=a.z===level?a:b.z===level?b:null;if(p)s+=`<circle cx="${p.x}" cy="${p.y}" r="8" fill="#d7f77c"/>`+txt(p.x,p.y+4,'↕',12,'#192b1d','text-anchor="middle"')}}const a=nodes[route[0]],b=nodes[route.at(-1)];if(a.z===level)s+=`<circle cx="${a.x}" cy="${a.y}" r="6" fill="#9de9e5" stroke="#18332b" stroke-width="2"/>`;if(b.z===level)s+=`<circle cx="${b.x}" cy="${b.y}" r="7" fill="#d7f77c" stroke="#18332b" stroke-width="2"/>`;}
// Labels sit on real footprints, with leaders where narrow platform spacing needs room.
if(level!==1){for(const p of STATION.platforms){const c=positions[p.number],x=c.x,y=c.y;const selected=$('#dest').value==='p'+p.number;s+=`<g class="hit" data-platform="${p.number}" role="button" tabindex="0" aria-label="${english?'Platform':'Peron'} ${p.number}"><circle cx="${x}" cy="${y}" r="12" fill="${selected?'#d7f77c':'#15271e'}" stroke="${selected?'#d7f77c':'#97ac7e'}" stroke-width="1"/>${txt(x,y+5,p.number,15,selected?'#17271b':'#eff4dc','text-anchor="middle" font-weight="700"')}</g>`;}}
const labels=[['old','STARY DWORZEC','OLD STATION'],['west','DWORZEC ZACHODNI','WEST STATION'],['summer','DWORZEC LETNI','SUMMER STATION'],['mall','AVENIDA','AVENIDA'],['hall','HALA DWORCA','STATION HALL']];
for(const [kind,pl,en]of labels){const b=STATION.buildings.find(b=>b.kind===kind),c=mean(b.points);if(kind==='hall'&&level!==1)continue;let x=c.x,y=c.y;if(kind==='west'){x-=55;y-=13}if(kind==='summer')y+=20;if(kind==='mall')y+=32;if(kind==='hall')y-=3;s+=txt(x,y,english?en:pl,kind==='mall'?17:11,kind==='hall'?'#e5edd4':'#a4b494','text-anchor="middle" paint-order="stroke" stroke="#203027" stroke-width="3"');}
s+=txt(640,154,'MOST DWORCOWY',9,'#93a887','transform="rotate(78 640 154)"');s+=line([[80,625],[174,625]],'#b6c99c',2)+line([[80,620],[80,630]],'#b6c99c',2)+line([[174,620],[174,630]],'#b6c99c',2)+txt(127,644,'100 m',10,'#b6c99c','text-anchor="middle"');
s+='</g>';svg.innerHTML=s;$('#levelTitle').textContent=english?({'1':'Station hall & Avenida','0':'Platform layout','-1':'Underground passage'})[level]:({'1':'Hala dworca i Avenida','0':'Układ peronów','-1':'Przejście podziemne'})[level];document.querySelectorAll('[data-level]').forEach(b=>b.classList.toggle('active',+b.dataset.level===level));svg.querySelectorAll('[data-platform]').forEach(el=>{const choose=()=>{$('#dest').value='p'+el.dataset.platform;calculate()};el.onclick=choose;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose()}}});}

function calculate(){route=findRoute($('#start').value,$('#dest').value);level=nodes[route[0]].z;const n=$('#dest').value.slice(1);$('#steps').innerHTML=english?`<h3>Demo route · Platform ${n}</h3><ol><li>Start: ${$('#start').selectedOptions[0].text}</li><li>Follow the line. Switch floors at ↕.</li><li>Destination: platform ${n}.</li></ol><p>Unverified connections. Do not use for travel.</p>`:`<h3>Trasa demo · Peron ${n}</h3><ol><li>Start: ${$('#start').selectedOptions[0].text}</li><li>Śledź linię. Przy ↕ przełącz poziom.</li><li>Cel: peron ${n}.</li></ol><p>Połączenia niezweryfikowane. Nie używaj do podróży.</p>`;render()}
for(let n=1;n<=11;n++)$('#dest').add(new Option('Peron '+n,'p'+n));$('#dest').value='p8';$('#route').onclick=calculate;document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=+b.dataset.level;render()});
function scale(d){zoom=Math.max(.6,Math.min(3,zoom*d));render()}$('#plus').onclick=()=>scale(1.2);$('#minus').onclick=()=>scale(1/1.2);$('#reset').onclick=()=>{zoom=1;pan=[0,0];render()};svg.addEventListener('wheel',e=>{e.preventDefault();scale(e.deltaY<0?1.08:1/1.08)},{passive:false});let drag;svg.onpointerdown=e=>{if(e.target.closest('[data-platform], [data-shop]'))return;drag={x:e.clientX,y:e.clientY,p:[...pan]};svg.setPointerCapture(e.pointerId)};svg.onpointermove=e=>{if(!drag)return;let k=1050/svg.getBoundingClientRect().width;pan=[drag.p[0]+(e.clientX-drag.x)*k,drag.p[1]+(e.clientY-drag.y)*k];render()};svg.onpointerup=svg.onpointercancel=()=>drag=null;
let watch=null;$('#gps').onclick=()=>{if(watch!==null){navigator.geolocation.clearWatch(watch);watch=null;$('#gps').textContent=english?'◎ Check my location':'◎ Sprawdź moją lokalizację';$('#gpsStatus').textContent=english?'Location stopped.':'Odczyt lokalizacji zatrzymany.';return}if(!navigator.geolocation){$('#gpsStatus').textContent='GPS unavailable / Lokalizacja niedostępna';return}$('#gpsStatus').textContent=english?'Waiting for a location reading…':'Oczekiwanie na pomiar lokalizacji…';watch=navigator.geolocation.watchPosition(p=>{$('#gps').textContent=english?'◎ Stop location':'◎ Zatrzymaj lokalizację';$('#gpsStatus').textContent=`${p.coords.latitude.toFixed(6)}, ${p.coords.longitude.toFixed(6)} · ±${Math.round(p.coords.accuracy)} m. `+(english?'Floor unknown. Map calibration pending.':'Piętro nieznane. Mapa wymaga kalibracji.')},e=>{$('#gpsStatus').textContent=({1:english?'Location permission denied. Enable it in your browser settings.':'Brak zgody na lokalizację. Możesz ją włączyć w ustawieniach przeglądarki.',2:english?'Location unavailable.':'Nie można ustalić lokalizacji.',3:english?'Location timed out. Try outdoors.':'Przekroczono czas pomiaru. Spróbuj na zewnątrz.'})[e.code];navigator.geolocation.clearWatch(watch);watch=null},{enableHighAccuracy:true,maximumAge:3000,timeout:15000})};
$('#lang').onclick=()=>{english=!english;document.documentElement.lang=english?'en':'pl';$('#lang').textContent=english?'PL':'EN';$('h1').innerHTML=english?'Find your<br><em>way.</em>':'Znajdź swoją<br><em>drogę.</em>';$('label[for="start"]').textContent=english?'WHERE ARE YOU?':'SKĄD RUSZASZ?';$('label[for="dest"]').textContent=english?'WHERE TO?':'DOKĄD IDZIESZ?';$('#route').innerHTML=english?'Show route <span>↗</span>':'Pokaż trasę <span>↗</span>';$('.notice').textContent=english?'PROTOTYPE • OSM geometry. Demo routes — require on-site verification.':'PROTOTYP • Geometria OSM. Trasy demonstracyjne — do weryfikacji na dworcu.';[...$('#dest').options].forEach((o,i)=>o.text=(english?'Platform ':'Peron ')+(i+1));[...$('#start').options].forEach((o,i)=>o.text=(english?['Station hall · +1','West station · −1','East end of tunnel · −1']:['Hala dworca · +1','Dworzec Zachodni · −1','Wschodni koniec tunelu · −1'])[i]);$('#gps').textContent=watch!==null?(english?'◎ Stop location':'◎ Zatrzymaj lokalizację'):(english?'◎ Check my location':'◎ Sprawdź moją lokalizację');$('.intro').innerHTML=english?'Choose your start and platform.<br>See how the levels connect.':'Wybierz miejsce startu i peron.<br>Zobacz, jak łączą się poziomy.';if(route.length)calculate();else render()};render();
